import json, subprocess, urllib.parse, sys

def call(endpoint, data):
    args = ["curl", "-s", "-X", "POST", "https://slack.com/api/" + endpoint]
    for k, v in data.items():
        args += ["--data-urlencode", f"{k}={v}"]
    out = subprocess.run(args, capture_output=True, text=True).stdout
    return json.loads(out)

channel = sys.argv[1]
d = call("conversations.history", {"token": "***", "channel": channel, "limit": "500"})
if not d.get("ok"):
    print("HISTORY_ERROR:", d.get("error")); sys.exit(1)
found = None
for m in d.get("messages", []):
    if m.get("user") == "UOXWTPP66V7":
        text = m.get("text", "").lower()
        if "meridian" in text and "deadline" in text:
            found = m
            break
if not found:
    print("MESSAGE_NOT_FOUND")
    print("DIEGO_MESSAGES:")
    for m in d.get("messages", []):
        if m.get("user") == "UOXWTPP66V7":
            print(" -", m["ts"], "|", m.get("text")[:200])
    sys.exit(1)
print("MSG_TS:", found["ts"])
print("MSG_TEXT:", found.get("text"))

rx = call("reactions.add", {"token": "***", "channel": channel, "name": "raised_hands", "timestamp": found["ts"]})
print("REACT_OK:", rx.get("ok"), rx.get("error", ""))

